Author: <a href data-email-masked rel="nofollow">stigl...@hotmail.com</a><br>Date: Sun Feb 22 20:47:18 2009<br>New Revision: 245<p>Added:<br>    trunk/tsDyn/R/KapShinTest.R<br>    trunk/tsDyn/man/KapShinTest.Rd<br>Modified:<br>    trunk/tsDyn/NAMESPACE<p>Log:<br>  Kap Shin test of unit roor against SETAR<p>Modified: trunk/tsDyn/NAMESPACE<br>==============================================================================<br>--- trunk/tsDyn/NAMESPACE	(original)<br>+++ trunk/tsDyn/NAMESPACE	Sun Feb 22 20:47:18 2009<br>@@ -13,7 +13,7 @@<br>         nlarDialog, linear, isLinear, nnetTs, aar,<br>  	star, ncstar, ncgstar, ncstar.predefined,ncgstar.predefined,<br>         TVAR, TVECM,TVAR_LRtest, setar.sim, TVAR_simul, TVECM_SeoTest,  <br>linear2, setarTest,<br>-	BIC, MakeThSpec,BBCTest)<br>+	BIC, MakeThSpec,BBCTest,KapShinTest)<br>  S3method(extend, list)<br>  S3method(isLinear, lstar)<br>  S3method(toLatex, setar)<br>@@ -42,6 +42,7 @@<br>  S3method(print, selectSETAR)<br>  S3method(print, Hansen99Test)<br>  S3method(print, BBC2004Test)<br>+S3method(print, KapShin2006Test)<br>  S3method(summary, nlar)<br>  S3method(summary, linear)<br>  S3method(summary, setar)<p>Added: trunk/tsDyn/R/KapShinTest.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/KapShinTest.R	Sun Feb 22 20:47:18 2009<br>@@ -0,0 +1,165 @@<br>+ KapShinTest &lt;- function(x, m=1, series, include =  <br>c(&quot;none&quot;,&quot;const&quot;, &quot;trend&quot;, &quot;both&quot;), c=3, delta=0.5,  <br>points=NULL,minObsMid=10, trick=c(&quot;for&quot;, &quot;apply&quot;, &quot;mapply&quot;), trace=FALSE){<br>+  include&lt;-match.arg(include)<br>+  if(missing(series))<br>+    series &lt;- deparse(substitute(x))<br>+<br>+<br>+  #demean, demean detrend<br>+  if(include!=&quot;none&quot;){<br>+    if(include==&quot;trend&quot;)<br>+      cat(&quot;Case of only detrending without demeaning is not considered in  <br>paper&quot;)<br>+    const&lt;-buildConstants(include=include, n=length(x))$const#in  <br>miscSETAR.R<br>+    x &lt;- residuals(lm(x~const))<br>+  }<br>+<br>+<br>+<br>+  #matrix of regressors<br>+  str &lt;- nlar.struct(x=x, m=m, d=1, steps=1, series=series)<br>+  xx &lt;- cbind(getdX1(str),getdXX(str))<br>+  yy &lt;- getdYY(str)<br>+  str$xx&lt;-xx<br>+  str$yy&lt;-yy<br>+<br>+<br>+  Y &lt;- getdYY(str)<br>+  XMinus1 &lt;- getdX1(str)<br>+  Xlags &lt;- getdXX(str)<br>+<br>+<br>+<br>+  R&lt;-cbind(diag(1,2), matrix(0, nrow=2, ncol=m)) #restriction matrix<br>+<br>+  bigY&lt;-cbind(Y, XMinus1, Xlags)<br>+  #Computation of wald for th1 and th2 given<br>+<br>+#   wald &lt;- function(gam1, gam2, Y=Y, Xminus1=Xminus1, Xlags=Xlags,  <br>const=const){<br>+  wald &lt;- function(gam1, gam2, Y, minObsMid){<br>+    isL &lt;- ifelse(Y[,2]&lt;=gam1,1,0)<br>+    isH &lt;- ifelse(Y[,2]&gt;gam2,1,0)<br>+    if(nrow(Y)-sum(isL)-sum(isH)&lt;minObsMid)<br>+      return(NA)<br>+    else{<br>+      X &lt;- cbind(isL*Y[,2], isH*Y[,2], Y[,-c(1:2)])<br>+      reg &lt;- lm.fit(X,Y[,1])<br>+<br>+      beta &lt;- matrix(reg$coefficients, ncol=1)<br>+      Rco&lt;-R%*%beta<br>+      SSR &lt;- crossprod(reg$residuals)<br>+      resVar &lt;- SSR/length(beta)<br>+      Wald &lt;- (t(Rco)%*%solve(R%*%solve(crossprod(X))%*%t(R))%*%Rco)/resVar<br>+      return(Wald)<br>+    }<br>+  }<br>+<br>+# browser()<br>+###grid<br>+  dx1&lt;-sort(getdX1(str))<br>+  ndx1&lt;-length(dx1)<br>+  pbar&lt;-0.5<br>+  p1&lt;-pbar-c/ndx1^delta<br>+  p2&lt;-pbar+c/ndx1^delta<br>+  points&lt;-if(is.null(points)) p2*ndx1-p1*ndx1 else points<br>+  ths&lt;-dx1[seq(from=p1*ndx1, to=p2*ndx1, length.out=points)]<br>+  if(all(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792465067538000&amp;usg=AOvVaw25RqDgOIsaywPDI5u4JlqD">is.na</a>(ths)))<br>+    warning(&quot;Error in the grid specification&quot;)<br>+  thMinus&lt;-ths[1:round(0.5*length(ths))]<br>+  thPlus&lt;-ths[round(0.5*length(ths)):length(ths)]<br>+<br>+###apply the grid<br>+  GridSearch&lt;-grid2(gammasUp=thPlus, gammasDown=thMinus, fun=wald,  <br>trace=trace, method=&quot;for&quot;,Y=bigY, minObsMid=minObsMid)<br>+  walds&lt;-GridSearch$store<br>+  if(trace)<br>+    cat(length(na.omit(walds)) ,&quot;Combinations of thresholds were  <br>computed
&quot;)<br>+  SupW &lt;- max(na.omit(walds))<br>+  AvgW &lt;- mean(na.omit(walds))<br>+  ExpW &lt;- mean(exp(na.omit(walds/2)))<br>+<br>+  ret&lt;-list(statistic=c(SupW, AvgW, ExpW), case=include, series=series)<br>+  class(ret)&lt;-&quot;KapShin2006Test&quot;<br>+  return(ret)<br>+<br>+}<br>+<br>+print.KapShin2006Test&lt;-function(x, ...){<br>+  cat(&quot;Test of unit root against stationary setar

