&quot;)<br>+<br>+}<br>+<br>+<br>+if(FALSE){<br>+library(tsDyn)<br>+environment(KapShinTest) &lt;- environment(star)<br>+KS&lt;-KapShinTest(lynx, m=1, trace=FALSE, include=&quot;none&quot;)<br>+KS&lt;-KapShinTest(lynx, m=1, trace=FALSE, points=10, include=&quot;none&quot;)<br>+KS$statistic<br>+KS<br>+}<br>+<br>+grid2&lt;-function(gammasUp, gammasDown, fun, trace=TRUE,  <br>method=c(&quot;for&quot;, &quot;apply&quot;, &quot;mapply&quot;),...){<br>+	store &lt;- matrix(NA,ncol=length(gammasUp), nrow=length(gammasDown))<br>+	method&lt;-match.arg(method)<br>+	if(method==&quot;for&quot;){<br>+		#Grid search<br>+		for(i in seq_len(length(gammasDown))){<br>+			gam1 &lt;- gammasDown[i]<br>+			for(j in 1: length(gammasUp)){<br>+				gam2 &lt;- gammasUp[j]<br>+				store[i,j] &lt;- fun(gam1=gam1, gam2=gam2,...)<br>+			}<br>+		}<br>+		#Finding the best result<br>+		positionIter &lt;- which(store==min(store, na.rm=TRUE), arr.ind=TRUE)<br>+		rIter &lt;- positionIter[1]<br>+		cIter &lt;- positionIter[2]<br>+	<br>+		gamma1Iter &lt;- gammasDown[rIter]<br>+		gamma2Iter &lt;- gammasUp[cIter]<br>+<br>+		bestThresh &lt;- c(gamma1Iter, gamma2Iter)<br>+	}<br>+	else if(method==&quot;apply&quot;){<br>+		grid&lt;-expand.grid(gammasDown,gammasUp)<br>+# 		fun(gam1=gam1, gam2=gam2, d=bestDelay)<br>+		temp&lt;-function(a) fun(gam1=c(a)[1],gam2=c(a)[2],...)<br>+		store&lt;-apply(grid,1,temp)<br>+		bests&lt;-which(store==min(store, na.rm=TRUE))<br>+		if(length(bests)&gt;1) {<br>+			warning(&quot;There were &quot;,length(bests), &quot; thresholds values which minimize  <br>the SSR in the first search, the first one was taken&quot;) 	<br>+			bests&lt;-bests[1]}<br>+# 		beta_grid&lt;-grid[bests,1]<br>+# 		bestGamma1&lt;-grid[bests,2]<br>+		bestThresh &lt;- c(grid[bests,1], grid[bests,2])<br>+	}<br>+	else if(method==&quot;mapply&quot;){<br>+		grid&lt;-expand.grid(gammasDown,gammasUp)	<br>+		store&lt;-mapply(fun, gam1=grid[,1],gam2=grid[,2], MoreArgs=list(...))<br>+		bests&lt;-which(store==min(store, na.rm=TRUE))<br>+		if(length(bests)&gt;1) {<br>+			warning(&quot;There were &quot;,length(bests), &quot; thresholds values which minimize  <br>the SSR in the first search, the first one was taken&quot;) 	<br>+			bests&lt;-bests[1]}<br>+# 		beta_grid&lt;-grid[bests,1]<br>+# 		bestGamma1&lt;-grid[bests,2]<br>+		bestThresh &lt;- c(grid[bests,1], grid[bests,2])<br>+	}<br>+	if(trace)<br>+		cat(&quot;
Second step best thresholds&quot;, bestThresh, &quot;		 SSR:&quot;, min(store,  <br>na.rm=TRUE), &quot;
&quot;)<br>+	return(list(bestThresh=bestThresh, store=store))<br>+}#end of grid function<br>+#  VAR&lt;-TVAR(dat[1:300,], lag=2, nthresh=2,thDelay=1, plot=FALSE,  <br>commonInter=TRUE, include=&quot;const&quot;, trick=&quot;apply&quot;, max.iter=5)<br>+<br>+#  system.time(TVAR(dat, lag=2, nthresh=2,thDelay=1, plot=FALSE,  <br>commonInter=TRUE, include=&quot;const&quot;, trick=&quot;apply&quot;))<br>+#  system.time(TVAR(dat, lag=2, nthresh=2,thDelay=1, plot=FALSE,  <br>commonInter=TRUE, include=&quot;const&quot;, trick=&quot;mapply&quot;))<br>+#  system.time(TVAR(dat, lag=2, nthresh=2,thDelay=1, plot=FALSE,  <br>commonInter=TRUE, include=&quot;const&quot;, trick=&quot;for&quot;))<br>+<br>+<p>Added: trunk/tsDyn/man/KapShinTest.Rd<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/man/KapShinTest.Rd	Sun Feb 22 20:47:18 2009<br>@@ -0,0 +1,43 @@<br>+
ame{KapShinTest}<br>+\alias{KapShinTest}<br>+\alias{KapShinTest}<br>+	itle{Test of unit root against SETAR alternative with}<br>+\description{Test of unit root against a stationnary 3 regime SETAR  <br>alternative with random walk in the inner regime<br>+}<br>+\usage{<br>+ KapShinTest(x, m=1, series, include = c(&quot;none&quot;,&quot;const&quot;, &quot;trend&quot;, &quot;both&quot;),  <br>c=3, delta=0.5, points=NULL,minObsMid=10,  <br>trick=c(&quot;for&quot;, &quot;apply&quot;, &quot;mapply&quot;), trace=FALSE)<br>+}<br>+<br>+<br>+\arguments{<br>+\item{x}{ time series }<br>+\item{m}{Number of lags under the alternative}<br>+\item{series}{ time series name (optional) }<br>+\item{include}{Whether data should be raw, de-menead or de-menead and  <br>de-trended}<br>+\item{c}{Argument for the grid search. See details}<br>+\item{delta}{Argument for the grid search. See details}<br>+\item{points}{Points for the grid search. See details}<br>+\item{minObsMid}{Minimal number of observations in the inner regime}<br>+\item{trick}{type of internal function used}<br>+\item{trace}{should additional infos be printed? (logical)}<br>+}<br>+<br>+\value{A object of class &quot;KapShin2006Test&quot; containing:<br>+\item{statistic}{The three (SupW, AvgW, ExpW) test statistics computed}<br>+\item{case}{Whether the data was transformed, corresponds to input  <br>argument include}<br>+\item{series}{The name of the series}<br>+<br>+}<br>+<br>+\details{<br>+This function is currently spurious.<br>+<br>+}<br>+\seealso{<br>+\code{\link{BBCTest}} for a similar test. \code{\link{setarTest}} for a  <br>test with stationarity as a null.<br>+}<br>+<br>+\author{ Matthieu Stigler}<br>+\examples{<br>+KapShinTest(lynx, m=1, trace=FALSE, include=&quot;none&quot;, points=10)<br>+}<br></p></p></p></p></p>
